graphql.query:
query FilterJobs($filters: JobFilters) {
  jobs(filters: $filters, limit: 20) {
    id
    title
    department
    location
    employmentType
    remoteWork
  }
}

query GetApplications($filters: ApplicationFilters, $limit: Int) {
  applications(filters: $filters, limit: $limit) {
    id
    status
    appliedDate
    job {
      id
      title
      department
    }
    candidate {
      id
      firstName
      lastName
      email
      phone
    }
    yearsOfExperience
    expectedSalary
    aiScore {
      overall
      recommendation
    }
  }
}

query GetApplication($appId: ID!) {
  application(id: $appId) {
    id
    status
    appliedDate
    lastUpdated
    job {
      id
      title
      department
    }
    candidate {
      id
      firstName
      lastName
      email
      phone
      location
      resumeUrl
      linkedinUrl
      skills
    }
    coverLetter
    yearsOfExperience
    expectedSalary
    availability
    aiScore {
      overall
      insights
      strengths
      concerns
      recommendation
      generatedAt
    }
    notes {
      id
      author {
        name
      }
      content
      createdAt
      isInternal
    }
    timeline {
      id
      type
      description
      performedBy {
        name
      }
      timestamp
    }
  }
}

mutation SubmitApplication($input: ApplicationInput!) {
  submitApplication(input: $input) {
    id
    status
    appliedDate
    job {
      id
      title
      department
    }
    candidate {
      id
      firstName
      lastName
      email
      phone
    }
    coverLetter
    yearsOfExperience
    expectedSalary
    aiScore {
      overall
      insights
      strengths
      concerns
      recommendation
      generatedAt
    }
  }
}

mutation IncrementJobView($jobId: ID!) {
  incrementJobView(id: $jobId) {
    id
    title
    viewCount
  }
}

mutation UpdateApplicationStatus($appId: ID!, $status: ApplicationStatus!, $note: String) {
  updateApplicationStatus(id: $appId, status: $status, note: $note) {
    id
    status
    lastUpdated
    notes {
      id
      content
      createdAt
    }
  }
}

graphql.variables:
{
  "appId": "{{applicationId}}",
  "status": "SCREENING",
  "note": "Moving to screening phase after initial review"
}

graphql.query:
mutation AddNote($appId: ID!, $content: String!, $isInternal: Boolean) {
  addApplicationNote(applicationId: $appId, content: $content, isInternal: $isInternal) {
    id
    content
    author {
      id
      name
    }
    createdAt
    isInternal
  }
}

